  <!-- Custom styles for bookings -->
  <style>
    .booking-card {
        border-radius: 10px;
        box-shadow: 0 0 20px rgba(0,0,0,0.1);
        transition: transform 0.3s ease;
    }
    .booking-card:hover {
        transform: translateY(-5px);
    }
    .status-badge {
        padding: 8px 15px;
        border-radius: 20px;
        font-weight: 600;
    }
    .status-active {
        background-color: #28a745;
        color: white;
    }
    .status-cancelled {
        background-color: #dc3545;
        color: white;
    }
    .filter-section {
        background: #f8f9fa;
        padding: 20px;
        border-radius: 10px;
        margin-bottom: 20px;
    }
    .table th {
        background: #1e3c72;
        color: white;
    }
    .action-buttons .btn {
        margin: 0 5px;
        border-radius: 20px;
    }
    .cancellation-reason {
        max-width: 200px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }
    .stats-card {
        border-radius: 10px;
        padding: 20px;
        margin-bottom: 20px;
        background: linear-gradient(45deg, #1e3c72, #2a5298);
        color: white;
    }
    .stats-number {
        font-size: 24px;
        font-weight: bold;
    }
  </style>

